WITH filtered_accounts AS (SELECT * FROM accounts WHERE balance > 57000 AND balance BETWEEN 41000 AND 45000), accounts_stats AS (SELECT CASE WHEN YEAR(opened_date) < 2024 THEN 'before_2024' WHEN YEAR(opened_date) = 2024 THEN '2024' ELSE 'after_2024' END AS opened_cohort, AVG(balance) AS avg_balance FROM filtered_accounts GROUP BY CASE WHEN YEAR(opened_date) < 2024 THEN 'before_2024' WHEN YEAR(opened_date) = 2024 THEN '2024' ELSE 'after_2024' END) SELECT opened_cohort, avg_balance FROM accounts_stats;
